/// Host-call micro-benchmark: kind 0 = rand_u32() (no args), kind 1 = terrain_height(x, z).
pub fn hostcalls(n: u32, kind: u32, host: &mut dyn Host) -> u32 {
    let mut acc = 0u32;
    for k in 0..n {
        if kind == 0 {
            acc = acc.wrapping_add(host.rand_u32());
        } else {
            acc = acc.wrapping_add(host.terrain_height(k as f32, acc as f32 * 1e-6).to_bits());
        }
    }
    acc
}

